INSERT INTO qa_rubric_versions (rubric_version, team_id, rubric_json, effective_from)
VALUES ('sofia_v0', 'sofia', '{"rubric_version":"sofia_v0","scoring_prompt":{"sop_sections":["sop_adherence","accuracy"],"confidence_levels_note":"- \"high\": Clear evidence in audio, no ambiguity\n- \"medium\": Reasonable inference, some ambiguity or audio-dependent nuance\n- \"low\": Insufficient signal, heavy guessing required","system_prompt_template":"You are a QA evaluator for {company}''s AI voice agent program.\nYou will listen to a full call recording taken by Sofia, {company}''s AI voice agent, and score it using the rubric provided.\nSofia is not a human agent: do not excuse errors on that basis, and score conversational naturalness exactly as the rubric defines it. Judge what a caller on the line would actually experience.\n\nCRITICAL OUTPUT RULES:\n- Return ONLY a valid JSON object. No markdown fences, no prose, no explanations outside the JSON.\n- All string values must have apostrophes and internal quotes escaped.\n- Never use raw newlines inside string values \u2014 use a space instead.\n- The JSON must be parseable by Python json.loads() without modification.\n- Use the Second person (\"you\") when referring to the agent (Sofia) in the reasoning AND feedback sections, as if you are directly addressing her with a personal tone, DO NOT use the Third person (\"they/them\") anywhere in your outputs.","audio_dependent_sections":["conversational_flow","tone_empathy"],"long_call_focus_sections":[]},"sections":[{"id":"sop_adherence","name":"SOP Adherence","auto_value":null,"history_id":"sop_adherence","score_type":"numeric","score_range":[1,5],"deprecated_at":null,"na_applicable":false,"confidence_cap":null,"section_number":1,"audio_dependent":false,"rubric_question":"Did Sofia follow the applicable Landing SOP(s) for the caller''s issue \u2014 required steps, correct information, proper process?","score_descriptions":{"1":"Ignored or contradicted the applicable SOP; handled the issue by improvisation","2":"Major SOP steps skipped or done out of order; outcome salvaged only by luck","3":"Core SOP followed with minor omissions that did not affect the outcome","4":"Followed the SOP correctly end-to-end with one cosmetic slip","5":"Followed the applicable SOP precisely, including edge-case handling"},"manual_default_value":null,"special_reasoning_instructions":"Ground this section in the SOP CONTEXT block when present. If no SOP context was retrieved for this call, score only what general Landing policy clearly requires and cap confidence at low."},{"id":"accuracy","name":"Accuracy & Policy Truthfulness","auto_value":null,"history_id":"accuracy","score_type":"numeric","score_range":[1,5],"deprecated_at":null,"na_applicable":false,"confidence_cap":null,"section_number":2,"audio_dependent":false,"rubric_question":"Was everything Sofia stated about Landing policy, the member''s account, pricing, or process actually true and grounded?","score_descriptions":{"1":"Fabricated policy, commitments, or account facts (hallucination with member impact)","2":"At least one materially wrong or unfounded claim, or promised an action she cannot take","3":"Accurate overall; minor imprecision with no member impact","4":"Accurate throughout; hedged appropriately when unsure","5":"Fully accurate and grounded; clearly separated facts from items needing human follow-up"},"manual_default_value":null,"special_reasoning_instructions":"Treat specific unverifiable claims (dates, amounts, policy exceptions) as inaccuracies unless supported by the call context. The audio is the source of truth."},{"id":"conversational_flow","name":"Human-Likeness: Conversational Flow","auto_value":null,"history_id":"conversational_flow","score_type":"numeric","score_range":[1,5],"deprecated_at":null,"na_applicable":false,"confidence_cap":null,"section_number":3,"audio_dependent":true,"rubric_question":"Did the conversation flow like a natural human call \u2014 timing, turn-taking, no awkward gaps, interruptions, or robotic loops?","score_descriptions":{"1":"Robotic: long dead air, talks over the caller repeatedly, loops or non-sequiturs","2":"Frequent unnatural pauses or interruptions; the caller had to repeat themselves","3":"Generally natural; occasional stilted timing a caller would notice","4":"Natural timing and turn-taking; at most one minor artifact","5":"Indistinguishable from a competent human agent in pacing and turn-taking"},"manual_default_value":null,"special_reasoning_instructions":"Use the PLATFORM SIGNAL MARKERS block (system-verified response-gap, interruption, silence, and latency measurements) as objective evidence for this section and cite the relevant measurements in the reasoning."},{"id":"tone_empathy","name":"Human-Likeness: Tone & Empathy","auto_value":null,"history_id":"tone_empathy","score_type":"numeric","score_range":[1,5],"deprecated_at":null,"na_applicable":false,"confidence_cap":null,"section_number":4,"audio_dependent":true,"rubric_question":"Did Sofia''s tone, word choice, and emotional responses fit the caller''s situation?","score_descriptions":{"1":"Flat or mismatched affect; ignored obvious frustration or distress","2":"Acknowledged emotion generically or late; scripted-sounding sympathy","3":"Appropriate tone; empathy present but shallow","4":"Warm, situationally appropriate tone; acknowledged the caller''s state naturally","5":"Genuinely human-feeling warmth; matched the caller''s register throughout"},"manual_default_value":null,"special_reasoning_instructions":null},{"id":"intent_resolution","name":"Intent Capture & Resolution","auto_value":null,"history_id":"intent_resolution","score_type":"numeric","score_range":[1,5],"deprecated_at":null,"na_applicable":false,"confidence_cap":null,"section_number":5,"audio_dependent":false,"rubric_question":"Did Sofia correctly identify what the caller needed and either resolve it or set up the right next step?","score_descriptions":{"1":"Misidentified the need; the caller left unresolved with no viable path","2":"Partially captured the need; resolution attempt off-target","3":"Captured the need; resolved or routed with minor gaps (e.g. a weak recap)","4":"Correctly resolved or routed with clear confirmation of next steps","5":"Fully resolved or perfectly routed, confirmed understanding, no loose ends"},"manual_default_value":null,"special_reasoning_instructions":"The CALL PLATFORM ANALYSIS block (Retell post-call summary and sentiment) is informational context, not ground truth \u2014 verify it against the audio."},{"id":"escalation_handling","name":"Escalation & Transfer Handling","auto_value":null,"history_id":"escalation_handling","score_type":"yn","score_range":null,"deprecated_at":null,"na_applicable":true,"confidence_cap":null,"section_number":6,"audio_dependent":false,"rubric_question":"When the call needed a human (explicit request, out-of-scope issue, or policy requirement), did Sofia recognize it and hand off correctly?","score_descriptions":{"0":"Missed a needed escalation, resisted a human request, or botched the transfer","1":"Recognized the escalation need promptly and completed the handoff correctly"},"manual_default_value":null,"special_reasoning_instructions":null,"na_applies_when":"No escalation, transfer, or human-handoff context arose during the call and none was warranted."}]}', '2026-08-10T00:00:00Z');

